"""Term reports built from the CSV files in records/."""

from __future__ import annotations

import csv

from gradebook.grades import average, letter


def load_scores(path: str) -> dict[str, list[float]]:
    """Each student's scores from a CSV file with student, subject, and score columns."""
    latest: dict[tuple[str, str], float] = {}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            if row["score"].strip():
                latest[(row["student"], row["subject"])] = float(row["score"])
    scores: dict[str, list[float]] = {}
    for (student, _subject), score in latest.items():
        scores.setdefault(student, []).append(score)
    return scores


def term_report(path: str) -> str:
    """One line per student, sorted by name, with the average and the letter grade."""
    lines = []
    for student, marks in sorted(load_scores(path).items()):
        mean = average(marks)
        lines.append(f"{student}: {mean} ({letter(mean)})")
    return "\n".join(lines)

