"""Letter grades and averages. Scores are out of 100."""

from __future__ import annotations

CUTOFFS = [(90, "A"), (80, "B"), (70, "C"), (60, "D")]


def letter(score: float) -> str:
    """Letter grade for a score."""
    for cutoff, grade in CUTOFFS:
        if score >= cutoff:
            return grade
    return "F"


def average(scores: list[float]) -> float:
    """Mean of the scores, rounded to one decimal place."""
    return round(sum(scores) / len(scores), 1)


def median(scores: list[float]) -> float:
    """Middle score; the mean of the two middle scores for an even count."""
    ordered = sorted(scores)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

